import { test, expect } from '@playwright/test';

test.describe('Notification Preferences Management', () => {
  test.beforeEach(async ({ page }) => {
    // Navigate to the application
    await page.goto('/');

    // Login if required (assuming there's a login flow)
    const loginButton = page.getByRole('button', { name: /sign in|login/i });
    if (await loginButton.isVisible()) {
      await loginButton.click();
      await page.getByLabel(/email|username/i).fill('testuser@example.com');
      await page.getByLabel(/password/i).fill('testpassword123');
      await page.getByRole('button', { name: /submit|sign in/i }).click();
      await page.waitForURL(/dashboard|home/);
    }

    // Navigate to settings
    const settingsButton = page.getByRole('button', { name: /settings/i });
    await settingsButton.click();
    await page.waitForURL(/settings/);
  });

  test('should display notification preferences section', async ({ page }) => {
    // Verify notification preferences section is visible
    const notificationSection = page.getByRole('heading', { name: /notification|preferences/i });
    await expect(notificationSection).toBeVisible();

    // Verify notification settings options are displayed
    const emailNotifications = page.getByLabel(/email notifications/i);
    await expect(emailNotifications).toBeVisible();

    const pushNotifications = page.getByLabel(/push notifications/i);
    await expect(pushNotifications).toBeVisible();

    const smsNotifications = page.getByLabel(/sms notifications/i);
    await expect(smsNotifications).toBeVisible();
  });

  test('should enable and disable email notifications', async ({ page }) => {
    // Find the email notifications toggle
    const emailToggle = page.getByLabel(/email notifications/i);

    // Get initial state
    const initialState = await emailToggle.isChecked();

    // Toggle the email notifications
    await emailToggle.click();

    // Verify the state changed
    const newState = await emailToggle.isChecked();
    expect(newState).not.toBe(initialState);

    // Verify success message appears
    const successMessage = page.getByText(/settings saved|preferences updated/i);
    await expect(successMessage).toBeVisible();
  });

  test('should manage notification frequency preferences', async ({ page }) => {
    // Find notification frequency dropdown
    const frequencyDropdown = page.getByLabel(/notification frequency|how often/i);
    await expect(frequencyDropdown).toBeVisible();

    // Click to open dropdown
    await frequencyDropdown.click();

    // Select a frequency option
    const dailyOption = page.getByRole('option', { name: /daily/i });
    await expect(dailyOption).toBeVisible();
    await dailyOption.click();

    // Verify selection was made
    await expect(frequencyDropdown).toHaveValue(/daily/i);
  });

  test('should toggle multiple notification types', async ({ page }) => {
    // Get all notification toggles
    const pushToggle = page.getByLabel(/push notifications/i);
    const smsToggle = page.getByLabel(/sms notifications/i);

    // Store initial states
    const pushInitialState = await pushToggle.isChecked();
    const smsInitialState = await smsToggle.isChecked();

    // Toggle both
    await pushToggle.click();
    await smsToggle.click();

    // Verify both changed
    const pushNewState = await pushToggle.isChecked();
    const smsNewState = await smsToggle.isChecked();

    expect(pushNewState).not.toBe(pushInitialState);
    expect(smsNewState).not.toBe(smsInitialState);

    // Verify save button is available
    const saveButton = page.getByRole('button', { name: /save|apply/i });
    await expect(saveButton).toBeVisible();
    await saveButton.click();

    // Verify confirmation
    const confirmationMessage = page.getByText(/saved successfully|changes applied/i);
    await expect(confirmationMessage).toBeVisible();
  });

  test('should configure notification categories', async ({ page }) => {
    // Find notification categories section
    const categoriesSection = page.getByRole('heading', { name: /notification categories|types/i });
    await expect(categoriesSection).toBeVisible();

    // Toggle specific category notifications
    const promotionalToggle = page.getByLabel(/promotional|marketing/i);
    const securityToggle = page.getByLabel(/security|account alerts/i);

    await expect(promotionalToggle).toBeVisible();
    await expect(securityToggle).toBeVisible();

    // Ensure security notifications cannot be disabled
    const securityInitialState = await securityToggle.isChecked();
    if (!securityInitialState) {
      await securityToggle.click();
    }

    // Toggle promotional notifications
    await promotionalToggle.click();

    // Save changes
    const saveButton = page.getByRole('button', { name: /save|apply/i });
    await saveButton.click();

    // Verify success
    const successMessage = page.getByText(/preferences updated|saved/i);
    await expect(successMessage).toBeVisible();
  });

  test('should reset notification preferences to defaults', async ({ page }) => {
    // Find reset button
    const resetButton = page.getByRole('button', { name: /reset|restore defaults/i });
    await expect(resetButton).toBeVisible();

    // Click reset
    await resetButton.click();

    // Confirm reset in dialog if present
    const confirmButton = page.getByRole('button', { name: /confirm|yes|reset/i });
    if (await confirmButton.isVisible()) {
      await confirmButton.click();
    }

    // Verify notification preferences are reset
    const emailToggle = page.getByLabel(/email notifications/i);
    const pushToggle = page.getByLabel(/push notifications/i);

    // Verify toggles are in default state (typically enabled)
    await expect(emailToggle).toBeChecked();
    await expect(pushToggle).toBeChecked();

    // Verify success message
    const successMessage = page.getByText(/reset successfully|defaults restored/i);
    await expect(successMessage).toBeVisible();
  });
});
